import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import React, { useState, createContext, useContext } from 'react';

export type Priority = 'Low' | 'Medium' | 'High' | 'Urgent';
export type Status = 'todo' | 'inprogress' | 'done';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: Status;
  priority: Priority;
  assignee: string;
}

interface KanbanContextType {
  tasks: Task[];
  moveTask: (taskId: string, newStatus: Status) => void;
  addTask: (task: Omit<Task, 'id'>) => void;
  filterStatus: Status | 'all';
  setFilterStatus: (status: Status | 'all') => void;
  draggedTaskId: string | null;
  setDraggedTaskId: (id: string | null) => void;
}

const KanbanContext = createContext<KanbanContextType | undefined>(undefined);

export const KanbanProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [tasks, setTasks] = useState<Task[]>([
    { id: '1', title: 'Design Landing Page', description: 'Create wireframes in Figma', status: 'todo', priority: 'High', assignee: 'Alice' },
    { id: '2', title: 'Setup Database', description: 'Configure PostgreSQL and Prisma', status: 'inprogress', priority: 'Urgent', assignee: 'Bob' },
    { id: '3', title: 'Authentication API', description: 'Implement JWT login endpoints', status: 'done', priority: 'Medium', assignee: 'Charlie' },
  ]);
  const [filterStatus, setFilterStatus] = useState<Status | 'all'>('all');
  const [draggedTaskId, setDraggedTaskId] = useState<string | null>(null);

  const moveTask = (taskId: string, newStatus: Status) => {
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: newStatus } : t));
  };

  const addTask = (newTask: Omit<Task, 'id'>) => {
    const id = Math.random().toString(36).substring(2, 9);
    setTasks(prev => [...prev, { ...newTask, id }]);
  };

  return (
    <KanbanContext.Provider value={{ tasks, moveTask, addTask, filterStatus, setFilterStatus, draggedTaskId, setDraggedTaskId }}>
      {children}
    </KanbanContext.Provider>
  );
};

export const useKanban = () => {
  const context = useContext(KanbanContext);
  if (!context) throw new Error('useKanban must be used within a KanbanProvider');
  return context;
};

import React from 'react';
import { useKanban, Task, Status, Priority } from './KanbanDragAndDropEngine';

const priorityColors: Record<Priority, string> = {
  Low: 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-300',
  Medium: 'bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300',
  High: 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300',
  Urgent: 'bg-rose-100 text-rose-700 dark:bg-rose-900/40 dark:text-rose-300',
};

export const KanbanBoard: React.FC = () => {
  const { tasks, moveTask, filterStatus, setFilterStatus, draggedTaskId, setDraggedTaskId } = useKanban();

  const columns: { id: Status; title: string }[] = [
    { id: 'todo', title: 'To Do' },
    { id: 'inprogress', title: 'In Progress' },
    { id: 'done', title: 'Done' },
  ];

  const handleDragOver = (e: React.DragEvent) => e.preventDefault();
  const handleDrop = (status: Status) => {
    if (draggedTaskId) {
      moveTask(draggedTaskId, status);
      setDraggedTaskId(null);
    }
  };

  const filteredTasks = tasks.filter(t => filterStatus === 'all' || t.status === filterStatus);

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 p-6 transition-colors duration-200">
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-2xl font-bold tracking-tight">Project Kanban</h1>
        <div className="flex gap-2 bg-slate-200 dark:bg-slate-900 p-1 rounded-lg">
          {(['all', 'todo', 'inprogress', 'done'] as const).map(status => (
            <button
              key={status}
              onClick={() => setFilterStatus(status)}
              className={`px-3 py-1.5 text-xs font-medium rounded-md capitalize transition-all ${
                filterStatus === status
                  ? 'bg-white dark:bg-slate-800 shadow text-slate-900 dark:text-white'
                  : 'text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'
              }`}
            >
              {status}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {columns.map(col => {
          const colTasks = filteredTasks.filter(t => t.status === col.id);
          return (
            <div
              key={col.id}
              onDragOver={handleDragOver}
              onDrop={() => handleDrop(col.id)}
              className="bg-slate-100/70 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 rounded-xl p-4 flex flex-col gap-4 min-h-[500px]"
            >
              <div className="flex justify-between items-center">
                <h2 className="font-semibold text-sm uppercase tracking-wider text-slate-500 dark:text-slate-400">{col.title}</h2>
                <span className="text-xs bg-slate-200 dark:bg-slate-800 px-2 py-0.5 rounded-full font-bold">
                  {colTasks.length}
                </span>
              </div>

              <div className="flex flex-col gap-3 flex-1">
                {colTasks.map(task => (
                  <div
                    key={task.id}
                    draggable
                    onDragStart={() => setDraggedTaskId(task.id)}
                    className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-4 rounded-lg shadow-sm hover:shadow-md cursor-grab active:cursor-grabbing transition-all"
                  >
                    <div className="flex justify-between items-start gap-2 mb-2">
                      <h3 className="font-medium text-sm">{task.title}</h3>
                      <span className={`text-[10px] px-2 py-0.5 rounded-full font-semibold ${priorityColors[task.priority]}`}>
                        {task.priority}
                      </span>
                    </div>
                    <p className="text-xs text-slate-500 dark:text-slate-400 mb-4">{task.description}</p>
                    <div className="flex justify-between items-center text-xs text-slate-400">
                      <span>Assignee: {task.assignee}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};
